const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/**
 * Cloud mask for Sentinel-2 images.
 * @param {ee.Image} image The Sentinel-2 image.
 * @return {ee.Image} The cloud-masked image.
 */
function maskS2clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000)
      .select(['B2', 'B3', 'B4']) // Blue, Green, Red
      .copyProperties(image, ['system:time_start']);
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kornwerderzand = ee.Geometry.Point([5.334, 53.076]); // East side of Ijsselmeer
  const afsluitdijk = ee.Geometry.Point([5.043, 52.937]);   // West side of Ijsselmeer
  const dateStart = '2023-07-08';
  const dateEnd = '2023-07-09';
  const scale = 30; // Use a reasonable scale for point analysis to avoid timeout

  // 2. Data Acquisition & Check
  let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(dateStart, dateEnd)
      .filterBounds(kornwerderzand.union(afsluitdijk));

  let imageCount = s2.size().getInfo();
  if (imageCount === 0) {
    console.log("No Sentinel-2 images found for the specified date.");
    console.log("A: No");
    return;
  }

  // 3. Processing
  const collection = s2.map(maskS2clouds);
  const image = collection.mosaic(); // Mosaic to get a single image for analysis

  // Define a greenness metric: Green / (Red + Blue)
  // This ratio will be higher for greener water.
  const greenness = image.expression(
    'G / (R + B)', {
      'G': image.select('B3'),
      'R': image.select('B4'),
      'B': image.select('B2')
    }).rename('greenness');

  // 4. Calculation
  const greennessKornwerderzand = greenness.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kornwerderzand,
    scale: scale,
    maxPixels: 1e9
  }).get('greenness');

  const greennessAfsluitdijk = greenness.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: afsluitdijk,
    scale: scale,
    maxPixels: 1e9
  }).get('greenness');

  const val1 = greennessKornwerderzand.getInfo();
  const val2 = greennessAfsluitdijk.getInfo();

  // 5. Validation & Final Answer
  if (val1 === null || val2 === null) {
      console.log(`Kornwerderzand value: ${val1}`);
      console.log(`Afsluitdijk value: ${val2}`);
      console.log("No valid pixels at one or both locations after cloud masking.");
      console.log("C2");
      return;
  }

  console.log(`Image Count: ${imageCount}`);
  console.log(`Greenness metric at Kornwerderzand: ${val1.toFixed(3)}`);
  console.log(`Greenness metric at Afsluitdijk: ${val2.toFixed(3)}`);

  if (isNaN(val1) || isNaN(val2)) {
    console.log("Calculation resulted in NaN.");
    console.log("C3");
    return;
  }

  if (val1 > val2) {
    console.log("Kornwerderzand was visibly greener than near Afsluitdijk.");
    console.log("A");
  } else {
    console.log("Kornwerderzand was NOT visibly greener than near Afsluitdijk.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
